<template>
	<view class="container">
		<u-loading-page :loading="true" v-if="load" fontSize="28rpx" />
		<block v-else>
			<view class="inner">
				<view class="form">
					<view class="form-row">
						<view class="row-left">手机号码</view>
						<view class="row-input">{{form.mobile}}</view>
					</view>
					<view class="form-row" v-if="regis_sms_enable==1">
						<view class="row-left">验证码</view>
						<view class="row-input">
							<u-input
								placeholder="请输入验证码"
								border="none"
								type="number"
								maxlength="6"
								placeholderClass="placeholder28"
								v-model="form.code"
								clearable />
						</view>
						<button type="default" size="mini" :disabled="codeDisabled" @click="getCode" class="code-btn">{{tips}}</button>
					</view>
					<view class="form-row">
						<view class="row-left">登录密码</view>
						<view class="row-input">
							<u-input 
							placeholder="请输入登录密码" 
							border="none" 
							type="text"
							placeholderClass="placeholder28" 
							password
							v-model="form.password" 
							clearable />
						</view>
					</view>
					<view class="form-row">
						<view class="row-left">确认密码</view>
						<view class="row-input">
							<u-input 
							placeholder="请输入确认密码" 
							border="none" 
							type="text"
							placeholderClass="placeholder28" 
							password
							v-model="form.conpassword" 
							clearable />
						</view>
					</view>
					<view class="form-row">
						<view class="row-left">推荐账号</view>
						<view class="row-input" v-if="rekey">{{rekey}}</view>
						<view class="row-input" v-else>
							<u-input 
							placeholder="请输入邀请码或手机号" 
							border="none" 
							type="text"
							placeholderClass="placeholder28" 
							v-model="form.rekey" 
							clearable />
						</view>
					</view>
				</view>
				<view class="submit">
					<button type="default" class="submit-btn" @click="get_bind_xinxi(2)"
						:disabled="submitDisabled || btnDisabled">提交</button>
				</view>
			</view>
		</block>
		<u-code ref="uCode1" startText="获取验证码" :seconds="sms_time_out" @change="codeChange" change-text="Xs"
										@start="codeDisabled = true" @end="codeDisabled = false"></u-code>
	</view>
</template>

<script>
	var validate = require("@/components/validate/validate.js");
	var _this;
	export default {
		data() {
			return {
				form:{
					step:1,
					mobile:uni.getStorageSync('mobile'),
					code:'',
					password:'',
					conpassword:'',
					rekey:uni.getStorageSync('rekey'),
					openid:uni.getStorageSync('openid')
				},
				rekey:uni.getStorageSync('rekey'),
				showNext:false,
				submitDisabled:false,
				result:{},
				tips:'获取验证码',
				xieyi:false,
				codeDisabled:false,
				regis_sms_enable:0,
				sms_time_out:60,
			}
		},
		onLoad(e) {
			_this = this;
			_this.get_bind_xinxi(1)
		},
		methods: {
			async get_bind_xinxi(step){
				_this.form.step = step
				if (_this.form.step == 2) {
					var rule = [{
						// 字段名
						name: 'mobile',
						rules: ['require', 'mobile'],
						errorMsg: {
							require: '请输入手机号码',
							mobile: '手机号码格式有误',
						}
					},
					{
						// 字段名
						name: 'password',
						rules: ['require', 'min:3'],
						errorMsg: {
							require: '请输入登录密码',
							min: '登录密码最少3位'
						}
					},{
						name: 'conpassword',
						rules: ['require', 'confirm:password'],
						errorMsg: {
							require: '请输入确认密码',
							confirm: '两次密码输入不一致'
						}
					}];
					let rekeyRule = {
						name: 'rekey',
						rules: ['require'],
						errorMsg: {
							require: '请输入邀请码或手机号',
						}
					}
					if (this.rekey=='' || this.rekey==undefined) {
						rule.push(rekeyRule)
					}
					// 是否全部通过，返回Boolean
					let checked = validate.check(this.form, rule);
					if (!checked) {
						// 获取错误信息
						let err = validate.getError();
						uni.$u.toast(err[0])
						return;
					}
					_this.submitDisabled = true
					setTimeout(()=>{
						_this.submitDisabled = false
					},2000)
				}
				const data = await _this.$post('port/wx_xcx_bangding_phone',_this.form)
				if (data.code==200) {
					uni.$u.toast(data.msg)
					//存入用户信息
					_this.$u.vuex('user_id',data.result.user_id)
					//存入token
					_this.$u.vuex('user_token', data.result.token)
					uni.removeStorageSync('mobile')
					uni.removeStorageSync('rekey')
					uni.$u.toast(data.msg,()=>{
						uni.reLaunch({
							url:'/pages/index/index'
						})
					})
				}else if(data.code == -1){
					_this.regis_sms_enable = data.result.regis_sms_enable
					_this.sms_time_out = data.result.sms_time_out
					if (_this.load) {
						_this.load = false
					}
				}else{
					uni.$u.toast(data.msg)
				}
			},
			//获取验证码
			async getCode() {
				//单独验证使用
				let check = validate.checkResult('mobile', this.form.mobile);
				if (!check) {
					uni.$u.toast("手机号码格式有误")
					return
				}
				if (this.$refs.uCode1.canGetCode) {
					const params = {
						mobile: this.form.mobile,
						scene: 2
					}
					const data = await _this.$post('port/send_code',params)
					if (data.code == 200) {
						// 这里此提示会被this.start()方法中的提示覆盖
						uni.$u.toast('发送成功');
						// 通知验证码组件内部开始倒计时
						this.$refs.uCode1.start();
					} else {
						// 这里此提示会被this.start()方法中的提示覆盖
						uni.$u.toast(data.msg);
					}
				} else {
					uni.$u.toast('请倒计时结束后再发送');
				}
			},
			codeChange(text) {
				this.tips = text;
			},
			goXieYi(){
				let url = encodeURIComponent('/port/xieyi_xq?id=1')
				_this.toNext(`/pages/index/html-detail?title=注册协议&url=${url}`)
			},
		},
		computed:{
			btnDisabled:{
				cache:false,
				get() {
					if (this.regis_sms_enable == 1) {
						return this.form.mobile == '' ||  this.form.code == '' || this.form.password == '' || this.form.conpassword=='' || this.form.rekey == ''
					}
					return this.form.mobile == '' ||  this.form.password == '' || this.form.conpassword=='' || this.form.rekey == ''
				}
			}
		}
	}
</script>

<style lang="scss" scoped>
	@import "static/css/form.scss";
	
	.container {
		height: 100%;
		position: relative;
		background: #fff;
	
		.inner {
			.form {
				.form-row {}
			}
		}
	}
</style>
